import AppKit

struct FileViewerSyntaxSpan: Decodable, Equatable {
    let begin: String
    let end: String?
    let eol: Bool
    let escape: String?
    let bol: Bool
    let kind: String
}

struct FileViewerSyntaxMode: Decodable, Equatable {
    let name: String
    let extensions: [String]
    let ignoreCase: Bool
    let delimiters: String
    let spans: [FileViewerSyntaxSpan]
    let keywords: [String]
}

enum FileViewerSyntaxRegistry {
    static let modes: [FileViewerSyntaxMode] = (try? JSONDecoder().decode([FileViewerSyntaxMode].self, from: Data(json.utf8))) ?? []

    private static let extensionTable: [(key: String, mode: Int)] = {
        var order: [String] = []
        var values: [String: Int] = [:]
        for (index, mode) in modes.enumerated() {
            for value in mode.extensions {
                let key = value.uppercased()
                if values[key] == nil { order.append(key) }
                values[key] = index
            }
        }
        return order.map { ($0, values[$0]!) }
    }()

    static func mode(for path: String?) -> FileViewerSyntaxMode? {
        guard let path, !path.isEmpty else { return nil }
        let upper = path.uppercased()
        guard let match = extensionTable.first(where: { upper.hasSuffix($0.key) }) else { return nil }
        return modes[match.mode]
    }

