enum FileViewerSyntaxTokenKind: Equatable {
    case comment
    case string
    case keyword
    case number
}

struct FileViewerSyntaxToken: Equatable {
    let range: NSRange
    let kind: FileViewerSyntaxTokenKind
}

enum FileViewerSyntaxLexer {
    private enum Part {
        case literal(UInt16)
        case notFollowed([UInt16])
        case notPreceded([UInt16])
        case boundary
    }

    private static func parse(_ pattern: String) -> [Part] {
        let units = Array(pattern.utf16)
        var parts: [Part] = []
        var index = 0
        while index < units.count {
            let unit = units[index]
            guard unit == 64, index + 1 < units.count else {
                parts.append(.literal(unit))
                index += 1
                continue
            }
            let special = units[index + 1]
            index += 2
            switch special {
            case 33, 45:
                var text: [UInt16] = []
                while index < units.count, units[index] != 64 { text.append(units[index]); index += 1 }
                index += 1
                parts.append(special == 33 ? .notFollowed(text) : .notPreceded(text))
            case 67:
                parts.append(.boundary)
            default:
                parts.append(.literal(64))
            }
        }
        return parts
    }

    private static func equal(_ a: UInt16, _ b: UInt16, ignoreCase: Bool) -> Bool {
        guard ignoreCase else { return a == b }
        func upper(_ value: UInt16) -> UInt16 { (97...122).contains(value) ? value - 32 : value }
        return upper(a) == upper(b)
    }

    private static func match(_ parts: [Part], in line: [UInt16], at index: Int, ignoreCase: Bool) -> Int? {
        var offset = 0
        for part in parts {
            switch part {
            case .literal(let unit):
                guard index + offset < line.count, equal(line[index + offset], unit, ignoreCase: ignoreCase) else { return nil }
                offset += 1
            case .notFollowed(let text):
                if index + offset + text.count <= line.count,
                   zip(text, line[(index + offset)...]).allSatisfy({ equal($1, $0, ignoreCase: ignoreCase) }) { return nil }
            case .notPreceded(let text):
                if index - text.count >= 0,
                   zip(text, line[(index - text.count)...]).allSatisfy({ equal($1, $0, ignoreCase: ignoreCase) }) { return nil }
            case .boundary:
                if index + offset > 0, index + offset < line.count,
                   let scalar = Unicode.Scalar(line[index + offset]),
                   !CharacterSet.whitespaces.contains(scalar), !CharacterSet.punctuationCharacters.contains(scalar) { return nil }
            }
        }
        return offset
    }

    private static func isDigit(_ unit: UInt16) -> Bool { (48...57).contains(unit) }

    static func tokens(_ text: String, mode: FileViewerSyntaxMode, openSpan: Int? = nil) -> (tokens: [FileViewerSyntaxToken], openSpan: Int?) {
        let begins = mode.spans.map { parse($0.begin) }
        let ends = mode.spans.map { $0.end.map(parse) }
        let delimiters = Set(mode.delimiters.utf16)
        let keywords = Set(mode.ignoreCase ? mode.keywords.map { $0.uppercased() } : mode.keywords)
        var tokens: [FileViewerSyntaxToken] = []
        var active = openSpan
        var location = 0
        for rawLine in text.split(separator: "\n", omittingEmptySubsequences: false) {
            let line = Array(String(rawLine).utf16)
            var spanStart = active == nil ? -1 : 0
            var wordStart = -1
            var lineHasWord = false
            func flushWord(_ end: Int) {
                guard wordStart >= 0 else { return }
                let word = String(utf16CodeUnits: Array(line[wordStart..<end]), count: end - wordStart)
                if keywords.contains(mode.ignoreCase ? word.uppercased() : word) {
                    tokens.append(.init(range: NSRange(location: location + wordStart, length: end - wordStart), kind: .keyword))
                }
                wordStart = -1
                lineHasWord = true
            }
            var index = 0
            while index < line.count {
                let unit = line[index]
                if let current = active {
                    let span = mode.spans[current]
                    if let escape = span.escape?.utf16.first, unit == escape {
                        if let end = span.end, end.utf16.count == 1, end.utf16.first == escape {
                            if index + 1 < line.count, line[index + 1] == escape { index += 2; continue }
                        } else {
                            index += 2
                            continue
                        }
                    }
                    if let endParts = ends[current], !endParts.isEmpty, let length = match(endParts, in: line, at: index, ignoreCase: mode.ignoreCase) {
                        index += max(1, length)
                        tokens.append(.init(range: NSRange(location: location + spanStart, length: index - spanStart), kind: span.kind == "comment" ? .comment : .string))
                        active = nil
                        continue
                    }
                    index += 1
                    continue
                }
                if unit == 32 || unit == 9 || unit == 13 { flushWord(index); index += 1; continue }
                if wordStart < 0, isDigit(unit) || (unit == 46 && index + 1 < line.count && isDigit(line[index + 1])) {
                    var end = index + 1
                    while end < line.count, isDigit(line[end]) || line[end] == 46 || (65...70).contains(line[end]) || (97...102).contains(line[end]) || line[end] == 120 || line[end] == 88 { end += 1 }
                    tokens.append(.init(range: NSRange(location: location + index, length: end - index), kind: .number))
                    lineHasWord = true
                    index = end
                    continue
                }
                var started = false
                for (spanIndex, parts) in begins.enumerated() {
                    let span = mode.spans[spanIndex]
                    if span.bol && (wordStart >= 0 || lineHasWord) { continue }
                    guard let length = match(parts, in: line, at: index, ignoreCase: mode.ignoreCase) else { continue }
                    flushWord(index)
                    active = spanIndex
                    spanStart = index
                    index += max(1, length)
                    started = true
                    break
                }
                if started { continue }
                if delimiters.contains(unit) {
                    flushWord(index)
                    lineHasWord = true
                    index += 1
                    continue
                }
                if wordStart < 0 { wordStart = index }
                index += 1
            }
            flushWord(line.count)
            if let current = active {
                tokens.append(.init(range: NSRange(location: location + spanStart, length: line.count - spanStart),
                                    kind: mode.spans[current].kind == "comment" ? .comment : .string))
                if mode.spans[current].eol { active = nil }
            }
            location += line.count + 1
        }
        return (tokens, active)
    }

    static func lineStates(_ lines: [String], mode: FileViewerSyntaxMode?) -> [Int?] {
        guard let mode else { return Array(repeating: nil, count: lines.count) }
        var state: Int?
        return lines.map { line in
            let start = state
            state = tokens(line, mode: mode, openSpan: state).openSpan
            return start
        }
    }
}
